do $$
declare v_orphans int;
begin
  select count(*) into v_orphans from public.passport_matches
   where season = 2012 and stadium is not null and venue_id is null;
  if v_orphans > 0 then
    raise exception 'ha % partidas de 2012 com estadio sem venue_id -- rode bragantino_passport_venues_seed.sql', v_orphans;
  end if;
end $$;
